sys_ux_data_broker_transform.props:
[
{
  "name": "taskList",
  "label": "List of Tasks",
  "description": "Input for the user tasks as csv",
  "readOnly": false,
  "fieldType": "string",
  "mandatory": true
}
]

sys_ux_data_broker_transform.script:
function transform(input) {
    var taskArr = input.taskList.split("$");
    // var unqiueTaskArr = [];

    // var userTaskObj = new GlideRecord("x_1324635_grc_ops_user_tasks");
    // userTaskObj.addQuery("task_name", "IN", taskArr);
    // userTaskObj.query();
    // while (userTaskObj.next()) {
    //     unqiueTaskArr.push(userTaskObj.task_name);
    // }

    var createTaskObj = new GlideRecord("x_1324635_grc_ops_user_tasks");
    for (var task in taskArr) {
        createTaskObj.initialize();
        createTaskObj.task_name = taskArr[task];
		createTaskObj.state = "1";
		createTaskObj.user = gs.getUserID();
		createTaskObj.insert();
    }

	return true;
}
